/**
 * Engine shared by every tool (browser-safe): the light centre list generated by scripts/update-data.py
 * from the DVSA tables, postcode districts from Ordnance Survey Code-Point Open, and the national
 * tables by age, sex and attempt. Pure functions, tested in tests/engine.test.ts. No figure is typed here.
 */
import LITE from '../../data/centres-lite.json';
import DISTRICTS from '../../data/districts.json';
import NAT from '../../data/national.json';
import THEORY from '../../data/theory.json';
import { P } from './params';

export interface Lite {
  id: string; n: string; r: string; c: 'E' | 'S' | 'W'; en: [number, number];
  /** Pass rate in % for the three latest financial years (LITE.years), null when fewer than 1 test. */
  p: Array<number | null>;
  /** Tests conducted in the latest year. */
  t: number;
  /** First-attempt pass rate %, automatic-car pass rate %, latest year. */
  f: number | null; a: number | null;
  /** Manual-car pass rate %, and first-attempt passes with zero driving faults (count). */
  mn: number | null; z: number | null;
  /** Median weeks between booking and test, and weeks before 10 % of tests had been booked, latest month. */
  w: number | null; w10: number | null;
  /** The 3 centres a test booked here can be moved to (DVSA list), by id. */
  nb: string[];
  lgv: boolean;
}
export const YEARS = LITE.years as string[];
export const LAST_YEAR = YEARS[YEARS.length - 1];
export const WAIT_MONTH = LITE.month as string;
export const CENTRES = LITE.centres as unknown as Lite[];
const BY_ID = new Map(CENTRES.map((c) => [c.id, c]));
export const centre = (id: string): Lite => { const c = BY_ID.get(id); if (!c) throw new Error(`Unknown centre ${id}`); return c; };
export const hasCentre = (id: string) => BY_ID.has(id);
export const COUNTRY: Record<Lite['c'], string> = { E: 'England', S: 'Scotland', W: 'Wales' };
export const REGIONS = ['London', 'South East', 'South West', 'East of England', 'East Midlands', 'West Midlands', 'North West', 'North East', 'Yorkshire and The Humber', 'Wales', 'Scotland'] as const;
export type Region = (typeof REGIONS)[number];
export const inRegion = (r: string) => CENTRES.filter((c) => c.r === r);
/** Latest pass rate in % (0-100), or null. */
export const rate = (c: Lite) => c.p[c.p.length - 1];
/** Change in points between the first and the last of the three years, or null. */
export const trend = (c: Lite) => (c.p[0] != null && rate(c) != null ? Math.round(((rate(c) as number) - (c.p[0] as number)) * 10) / 10 : null);
export const sorted = (list: Lite[], by: 'rate' | 'wait' | 'tests' | 'name', asc = false) => {
  const v = (c: Lite) => (by === 'rate' ? rate(c) : by === 'wait' ? c.w : by === 'tests' ? c.t : null);
  return [...list].sort((a, b) => {
    if (by === 'name') return a.n.localeCompare(b.n, 'en-GB');
    const x = v(a), y = v(b);
    if (x == null) return 1; if (y == null) return -1;
    return asc ? x - y : y - x;
  });
};

/* ---------------- Postcodes and distances ---------------- */
const D = DISTRICTS as unknown as Record<string, [number, number]>;
export interface Place { e: number; n: number; label: string; kind: 'district' | 'centre' }
const norm = (s: string) => s.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g, '');
/** A full postcode (SW1A 1AA), an outward code (NW9) or a centre name; null when nothing matches. */
export function findPlace(q: string): Place | null {
  const s = q.trim().toUpperCase().replace(/\s+/g, ' ');
  if (!s) return null;
  const compact = s.replace(/ /g, '');
  const full = compact.match(/^([A-Z]{1,2}\d[A-Z\d]?)(\d[A-Z]{2})$/);
  const outward = full ? full[1] : s.split(' ')[0];
  if (D[outward]) return { e: D[outward][0], n: D[outward][1], label: outward, kind: 'district' };
  const k = norm(q);
  if (k.length < 3) return null;
  const hit = CENTRES.find((c) => norm(c.n) === k) ?? CENTRES.find((c) => norm(c.n).startsWith(k)) ?? CENTRES.find((c) => norm(c.n).includes(k));
  return hit ? { e: hit.en[0], n: hit.en[1], label: hit.n, kind: 'centre' } : null;
}
/** Straight-line distance in miles between two British National Grid points given in km. */
export const miles = (a: [number, number] | { e: number; n: number }, b: [number, number]) => {
  const [e, n] = Array.isArray(a) ? a : [a.e, a.n];
  return Math.hypot(e - b[0], n - b[1]) / 1.609344;
};
export interface Near extends Lite { d: number }
/** Centres within `radius` miles of a place, nearest first. */
export function near(p: { e: number; n: number }, radius: number, limit = 40): Near[] {
  return CENTRES.map((c) => ({ ...c, d: miles(p, c.en) })).filter((c) => c.d <= radius).sort((a, b) => a.d - b.d).slice(0, limit);
}
/** The centre with the highest latest pass rate within `radius` miles (with at least `minTests` tests). */
export function easiest(p: { e: number; n: number }, radius: number, minTests = 300): Near | null {
  const l = near(p, radius, 400).filter((c) => rate(c) != null && c.t >= minTests);
  return l.length ? l.reduce((a, b) => ((rate(b) as number) > (rate(a) as number) ? b : a)) : null;
}

/* ---------------- National tables ---------------- */
type Pair = [number, number];
const pr = (x: Pair) => x[1] / x[0];
export const NATIONAL = NAT;
export const gbRate = (year = LAST_YEAR) => pr((NAT.practical as Record<string, Record<string, Pair>>)[year].t);
export const gbFirst = (year = LAST_YEAR) => { const f = (NAT.first as Record<string, number[]>)[year]; return f[1] / f[0]; };
export const gbAuto = (year = LAST_YEAR) => pr((NAT.auto as Record<string, Pair>)[year]);
export const gbTheory = (year = LAST_YEAR) => pr((NAT.theory as Record<string, Record<string, Pair>>)[year].t);
export const gbSex = (s: 'm' | 'f', year = LAST_YEAR) => pr((NAT.practical as Record<string, Record<string, Pair>>)[year][s]);
const AGE = NAT.ageSex.rows as Record<string, Partial<Record<'m' | 'f' | 't', Pair>>>;
const ageKey = (age: number) => (age >= 60 ? '60 and over' : String(Math.max(16, Math.min(59, Math.round(age)))));
/** National pass rate of an age (and sex) in the latest year of DRT121C. */
export function ageRate(age: number, sex: 'm' | 'f' | 't' = 't') { const r = AGE[ageKey(age)]?.[sex]; return r ? pr(r) : null; }
const AGE_ALL = AGE.Total?.t ? pr(AGE.Total.t) : gbRate();
/**
 * Estimated chance of passing at one centre for one age and sex (an estimate, not a DVSA figure):
 * the centre's own latest pass rate multiplied by the ratio between the national rate of that age and sex
 * and the national rate of all candidates. Capped between 1 % and 99 %.
 */
export function odds(centreRate: number, age: number, sex: 'm' | 'f' | 't') {
  const a = ageRate(age, sex);
  const factor = a == null ? 1 : a / AGE_ALL;
  return { p: Math.max(0.01, Math.min(0.99, centreRate * factor)), factor, national: a };
}
const ATT = NAT.attempts.rows.t as Record<string, Pair>;
export const ATTEMPT_KEYS = Object.keys(ATT);
/** National pass rate at the n-th attempt (6 = six or more). */
export const attemptRate = (n: number) => pr(ATT[n >= 6 ? '6 or more' : String(n)]);
/** Chance of having passed within n attempts at a centre, each attempt scaled by the national attempt profile. */
export function withinAttempts(centreRate: number, n: number) {
  let fail = 1;
  for (let i = 1; i <= n; i++) fail *= 1 - Math.max(0.01, Math.min(0.99, centreRate * attemptRate(i) / gbRate()));
  return 1 - fail;
}
/** Average number of attempts to pass, when every attempt has the same chance p (geometric law). */
export const expectedAttempts = (p: number) => 1 / Math.max(0.01, p);

/* ---------------- Theory centres ---------------- */
export interface TheoryCentre { id: string; name: string; pass: Record<string, Pair>; sex: { m: Pair; f: Pair } }
export const THEORY_CENTRES = THEORY as unknown as TheoryCentre[];
export const theoryRate = (t: TheoryCentre, year = LAST_YEAR) => (t.pass[year] ? pr(t.pass[year]) : null);

/* ---------------- Cost of a licence ---------------- */
export interface CostInput { hours: number; price: number; passRate: number; theoryRate: number; evening: boolean; licence: 'online' | 'post' }
/**
 * Expected cost of getting a full car licence: lessons (hours x price, the learner's own figures), the
 * provisional licence, the theory and practical fees of GOV.UK multiplied by the expected number of
 * attempts at each (1 / pass rate). An estimate: lessons before a retest are not added.
 */
export function licenceCost(i: CostInput) {
  const F = P.fees;
  const lessons = Math.max(0, i.hours) * Math.max(0, i.price);
  const theoryTries = expectedAttempts(i.theoryRate);
  const practicalTries = expectedAttempts(i.passRate);
  const theory = F.theory * theoryTries;
  const practical = (i.evening ? F.practicalEvening : F.practicalWeekday) * practicalTries;
  const licence = i.licence === 'post' ? F.provisionalPost : F.provisionalOnline;
  return { lessons, theory, practical, licence, total: lessons + theory + practical + licence, theoryTries, practicalTries };
}
/** Median absolute change of a centre's pass rate between the last two years, in points (centres with 1,000 tests or more). */
export const SWING = (() => {
  const v = CENTRES.filter((c) => c.t >= 1000 && c.p[c.p.length - 1] != null && c.p[c.p.length - 2] != null).map((c) => Math.abs((c.p[c.p.length - 1] as number) - (c.p[c.p.length - 2] as number))).sort((a, b) => a - b);
  return v.length ? Math.round(v[Math.floor(v.length / 2)] * 10) / 10 : 0;
})();
